"use client";

import {
  createContext,
  useContext,
  ReactNode,
  useEffect,
  useSyncExternalStore,
} from "react";

export type Lang = "en" | "zh";

type Ctx = {
  lang: Lang;
  setLang: (l: Lang) => void;
  toggle: () => void;
};

const LanguageContext = createContext<Ctx | null>(null);

const STORAGE_KEY = "crabai-lang";

// useSyncExternalStore is the React 19 / Next.js 16-recommended hook for
// reading from an external store (localStorage). It uses getServerSnapshot
// during SSR and the initial hydration render, then switches to
// getClientSnapshot on the next tick — so there's no hydration mismatch
// and no need for a manual mounted flag.
function subscribe(callback: () => void) {
  if (typeof window === "undefined") return () => {};
  window.addEventListener("storage", callback);
  return () => window.removeEventListener("storage", callback);
}

function getClientSnapshot(): Lang {
  const saved = window.localStorage.getItem(STORAGE_KEY) as Lang | null;
  return saved === "en" || saved === "zh" ? saved : "en";
}

function getServerSnapshot(): Lang {
  return "en";
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  const lang = useSyncExternalStore(subscribe, getClientSnapshot, getServerSnapshot);

  const setLang = (l: Lang) => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(STORAGE_KEY, l);
    // Dispatch a synthetic storage event so useSyncExternalStore re-reads
    // within the same tab (the native storage event only fires in other tabs).
    window.dispatchEvent(new StorageEvent("storage", { key: STORAGE_KEY, newValue: l }));
  };

  const toggle = () => setLang(lang === "en" ? "zh" : "en");

  // Keep <html lang> attribute in sync (this is a side effect, not a state update).
  useEffect(() => {
    document.documentElement.lang = lang === "zh" ? "zh-CN" : "en";
  }, [lang]);

  // Sync <title> and <meta name="description"> with the active language so
  // search engine crawlers that execute JS (Googlebot) see the localized
  // version, and users who share the page on social get the right preview.
  useEffect(() => {
    const TITLE = lang === "zh"
      ? "crabAI — 定制 RAG 与 SQL 智能体工程 | AI 工程师服务"
      : "crabAI — Custom RAG & SQL Agent Engineering | Hire an AI Engineer";
    const DESC = lang === "zh"
      ? "雇佣私人 AI 工程师，为你的数据构建生产级定制 RAG 系统与自然语言 SQL 智能体。FAISS + Groq + LangChain。2 周交付 MVP。带引用、有评估、零幻觉。支持 SOC 2 / GDPR / HIPAA 合规。"
      : "Hire a private AI engineer to build production-grade custom RAG systems and natural-language SQL agents for your data. FAISS + Groq + LangChain. 2-week MVP. Citations, evals, zero hallucinations. SOC 2 / GDPR / HIPAA ready.";

    document.title = TITLE;
    const meta = document.querySelector('meta[name="description"]');
    if (meta) meta.setAttribute("content", DESC);
    const ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle) ogTitle.setAttribute("content", TITLE);
    const ogDesc = document.querySelector('meta[property="og:description"]');
    if (ogDesc) ogDesc.setAttribute("content", DESC);
  }, [lang]);

  return (
    <LanguageContext.Provider value={{ lang, setLang, toggle }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLang(): Ctx {
  const ctx = useContext(LanguageContext);
  if (!ctx) {
    // Fallback so server-rendered or out-of-provider components don't crash.
    return {
      lang: "en",
      setLang: () => {},
      toggle: () => {},
    };
  }
  return ctx;
}
